window.kbPageData["views/entry/k-6e663bb030341b18"] = {"key":"entry/k-6e663bb030341b18","state":{"route":"entry/k-6e663bb030341b18"},"node":{"id":"k-6e663bb030341b18","mode":"k","title":"国内大循环","type":"概念与词义","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":["政治理论必刷100题#21","政治理论必刷100题#29"],"current":true,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":0,"reviewSet":"多题条目","independentCount":2,"tags":{"主类":["概念与词义"],"出处性质":["专项题解析","机构注释"],"学科":["经济"],"来源主题":["经济指标与宏观调控"],"资料类别":["政治理论专项","非时政"]},"directorySummary":"国内大循环是国民经济的生产、分配、交换、消费等环节在国内相互衔接、持续运行所形成的经济循环。它是国内国际双循环相互促进的新发展格局的主体。","review":{"title":"国内大循环","type":"概念与词义","definition":"国内大循环是国民经济的生产、分配、交换、消费等环节在国内相互衔接、持续运行所形成的经济循环。它是国内国际双循环相互促进的新发展格局的主体。","explanation":"畅通国内大循环有赖于各环节协同发力，使生产要素在各环节有机衔接、循环流转。党的二十大报告提出，依托我国超大规模市场优势，以国内大循环吸引全球资源要素，增强国内国际两个市场两种资源联动效应。","basis":"据关联原题及所列出处编释。","references":[{"source":"twenty","location":"加快构建新发展格局"}],"related":["k-0a6da28c772630a4"],"domain":"经济","examFocus":{"政治理论必刷100题#21":"核对高水平对外开放的相关表述，区分吸引全球资源要素的依托与国内国际市场之间的联动。","政治理论必刷100题#29":"辨别新发展格局中的因果关系，分清哪一循环的畅通带来对全球资源要素吸引力的增强。"}},"aspects":[{"title":"国内循环对全球资源要素的吸引","uses":[{"unit":"Q1","role":"解题依据","use":"④将党的二十大报告中吸引全球资源要素所依托的国内大循环写成国际大循环，因而不能列入正确组合。","evidence":"依托我国超大规模市场优势，以国内大循环吸引全球资源要素","qids":["政治理论必刷100题#21"]},{"unit":"Q2","role":"直接考查","use":"题目要求选出关于新发展格局的不正确表述。2020年《求是》刊载的《国家中长期经济社会发展战略若干重大问题》将全球资源要素吸引力的增强与国内循环更加顺畅相联系。A项把这里的国内循环写成国际循环，因此选A。","evidence":"国内循环越顺畅，越能形成对全球资源要素的引力场","qids":["政治理论必刷100题#29"]}]}],"sources":[{"id":"b524569d860543e7","label":"国内大循环","topic":"经济指标与宏观调控","category":"非时政","text":"1.国内大循环\n面对外部环境的不确定性，习近平总书记提出的“以国内大循环为主体、国内国际双循\n环相互促进”的新发展格局，既是应对全球治理体系变革的战略选择，更是发挥大国经济内\n生优势的必然要求。做强国内大循环，就是将发展的立足点牢牢置于扩大内需战略基点。","source":{"doc":"6cbfb01fe723bba64b75","first":17,"last":17,"page":17,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#21":{"paper":"政治理论必刷100题","n":21,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",6],"asrc":["国省考政治理论必刷100题.pdf",44],"card":"980996764404edeabd39ba8b","links":[{"id":"k-6e663bb030341b18","role":"解题依据","why":"国内大循环依托超大规模市场吸引全球资源要素，并增强国内国际市场和资源联动。"}]},"政治理论必刷100题#29":{"paper":"政治理论必刷100题","n":29,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",9],"asrc":["国省考政治理论必刷100题.pdf",49],"card":"a883db405759b5a120337a1d","links":[{"id":"k-6e663bb030341b18","role":"直接考查","why":"畅通作为主体的国内大循环能够增强对全球资源要素的吸引力，促进国内国际双循环。"}]}},"terms":{"k-0a6da28c772630a4":{"id":"k-0a6da28c772630a4","mode":"k","type":"概念与词义","title":"全国统一大市场","qs":[],"count":4}},"references":{"twenty":{"name":"党的二十大报告（2022年）","url":"https://www.miit.gov.cn/xwdt/szyw/art/2022/art_d664717b51f54b9886bc371c5f3594ed.html"}},"topics":[],"units":{"k-6e663bb030341b18":[["政治理论必刷100题#21"],["政治理论必刷100题#29"]]}};
